using System;
using Ashfall.Core;
using Ashfall.Modules.WeaponHandling;
using Ashfall.Integration.DesktopPlaytest.Combat;
using Ashfall.Integration.Playable.HandsWeapons;
static class SmgCases
{
 static int count;
 static void Check(bool value,string label){if(!value)throw new Exception(label);count++;Console.WriteLine("PASS "+label);}
 static bool Near(float a,float b){return Math.Abs(a-b)<.00002f;}
 sealed class Query:IInteractionQuery{public bool Clear=true;public bool HasLineOfSight(string a,string b,Float3 c,Float3 d,float r){return Clear;}}
 static HandlingInput Input(bool trigger=false,bool grip=false,Float3 point=new Float3(),bool left=false){return new HandlingInput{Enabled=true,PrimaryTracked=true,SupportTracked=true,Trigger=trigger,Grip=grip,SupportLocal=point,LeftHanded=left,ForegripDistance=1};}
 static LocalRifleSandbox Gun(SourceRifleDefinition profile,R23RifleReserve pool){return new LocalRifleSandbox(new string[0],new Query(),profile,pool,"source/"+profile.Id);}
 static int Main(){try{
  var profiles=new[]{SourceRifleDefinition.Ump,SourceRifleDefinition.P90,SourceRifleDefinition.Mp5,SourceRifleDefinition.Mp9};int[] caps={28,45,21,24};float[] rates={14,15,13,12.5f},body={19,20,22,21},head={23,22,33,26};
  for(int i=0;i<profiles.Length;i++){
   var p=profiles[i];Check(p.Capacity==caps[i]&&Near(p.Interval,1/rates[i])&&!p.SemiAutomatic&&p.AmmoFamily=="smg"&&p.BodyDamage==body[i]&&p.HeadDamage==head[i],p.Id+" actual current catalog/rate/0991 damage and live sharedSMG family");
   var pool=new R23RifleReserve(1200);var gun=Gun(p,pool);gun.SuspendControls();Check(!gun.StepSource(.1f,Input(true),HandlingAction.Sample,false),p.Id+" selected native instance requires neutral trigger");gun.StepSource(0,Input(),HandlingAction.Sample,false);Check(gun.StepSource(0,Input(true),HandlingAction.Sample,false)&&gun.Snapshot.Loaded==p.Capacity-1,p.Id+" actual native accepted discharge consumes one round");Check(!gun.StepSource(p.Interval*.4f,Input(true),HandlingAction.Sample,false),p.Id+" source cadence refuses early held-trigger shot");Check(gun.StepSource(p.Interval*.6f,Input(true),HandlingAction.Sample,false)&&gun.Snapshot.Loaded==p.Capacity-2,p.Id+" actual automatic interval continues held trigger");
   int loaded=gun.LoadedRounds;gun.StepSource(.25f,Input(true),HandlingAction.Sample,true);Check(gun.LoadedRounds==loaded&&!gun.StepSource(.25f,Input(true),HandlingAction.Sample,false),p.Id+" pause/custody cannot consume ammo or resume held firing");
   gun.StepSource(0,Input(),HandlingAction.Sample,false);gun.StepSource(0,Input(),HandlingAction.Eject,false);Check(gun.Snapshot.Phase==ReloadPhase.NeedsMagazine&&pool.Available==1200+loaded,p.Id+" real VR Eject refunds native loaded rounds to finite shared family");
  }
  var ump=SourceRifleDefinition.Ump;Check(ump.ModelScale==.7182f&&ump.ReloadScale==1&&Near(ump.Insert.Y,-.147870724f*.7182f)&&Near(ump.Offer.Y,(-.147870724f-.168f)*.7182f),"UMP logical reload scale1 remains distinct from Aggressor display.7182");
  var upool=new R23RifleReserve(1200);var u=Gun(ump,upool);u.StepSource(0,Input(),HandlingAction.Eject,false);u.StepSource(0,Input(false,false,ump.Offer),HandlingAction.Sample,false);u.StepSource(0,Input(false,true,ump.Offer),HandlingAction.Sample,false);Check(u.Snapshot.Phase==ReloadPhase.HeldMagazine,"UMP actual physical magazine acquisition uses scaled source physical offer");u.StepSource(0,Input(false,true,ump.Insert),HandlingAction.Sample,false);Check(u.Snapshot.Phase==ReloadPhase.NeedsRack&&u.Snapshot.Seated==28&&upool.Available==1200,"UMP upward source stroke seats real28-round native magazine without double scale");u.StepSource(0,Input(false,false,ump.Charging),HandlingAction.Sample,false);u.StepSource(0,Input(false,true,ump.Charging),HandlingAction.Sample,false);u.StepSource(.12f,Input(false,true,new Float3(ump.Charging.X,ump.Charging.Y,ump.Charging.Z-.076f)),HandlingAction.Sample,false);Check(u.Snapshot.Chambered&&u.LoadedRounds==28,"UMP separate physical charging handle chambers actual seated rounds");
  var p90=SourceRifleDefinition.P90;var ppool=new R23RifleReserve(1200);var pgun=Gun(p90,ppool);pgun.StepSource(0,Input(),HandlingAction.Eject,false);pgun.StepSource(0,Input(false,false,p90.Offer),HandlingAction.Sample,false);pgun.StepSource(0,Input(false,true,p90.Offer),HandlingAction.Sample,false);Check(pgun.Snapshot.Phase==ReloadPhase.HeldMagazine&&p90.TopFeed&&p90.Offer.Z<p90.Insert.Z,"P90 actual raised/back top offer acquires native magazine");pgun.StepSource(0,Input(false,true,new Float3(p90.Offer.X,p90.Offer.Y+.15f,p90.Offer.Z)),HandlingAction.Sample,false);Check(pgun.Snapshot.Phase==ReloadPhase.HeldMagazine,"P90 upward gesture cannot masquerade as required FORWARD reload");pgun.StepSource(0,Input(false,true,new Float3(p90.Offer.X,p90.Offer.Y,p90.Offer.Z+.09f)),HandlingAction.Sample,false);Check(pgun.Snapshot.Phase==ReloadPhase.HeldMagazine,"P90 less-than.10 forward travel cannot seat top magazine");pgun.StepSource(0,Input(false,true,p90.Insert),HandlingAction.Sample,false);Check(pgun.Snapshot.Phase==ReloadPhase.NeedsRack&&pgun.Snapshot.Seated==45&&ppool.Available==1200,"P90 source FORWARD stroke seats actual45 rounds through native owner");pgun.StepSource(0,Input(),HandlingAction.Eject,false);Check(pgun.Snapshot.Phase==ReloadPhase.NeedsMagazine&&pgun.Snapshot.Seated==0&&ppool.Available==1245,"P90 real Eject while seated refunds magazine instead of false desktop auto-charge");
  pgun.StepSource(0,Input(false,false,p90.Offer,true),HandlingAction.Sample,false);pgun.StepSource(0,Input(false,true,p90.Offer,true),HandlingAction.Sample,false);pgun.StepSource(0,Input(false,true,p90.Insert,true),HandlingAction.Sample,false);var charge=p90.ChargingPoint(true);Check(charge.X==.05f&&p90.ChargingPoint(false).X==-.05f,"P90 source manual handle X mirrors only with dominance");pgun.StepSource(0,Input(false,false,charge,true),HandlingAction.Sample,false);pgun.StepSource(0,Input(false,true,charge,true),HandlingAction.Sample,false);pgun.StepSource(.12f,Input(false,true,new Float3(charge.X,charge.Y,charge.Z-.076f),true),HandlingAction.Sample,false);Check(pgun.Snapshot.Phase==ReloadPhase.Ready&&pgun.Snapshot.Chambered&&pgun.Snapshot.Loaded==45&&ppool.Available==1200,"P90 released/regripped mirrored BACK stroke chambers same finite magazine");
  foreach(var profile in new[]{SourceRifleDefinition.Mp5,SourceRifleDefinition.Mp9}){var pool=new R23RifleReserve(1200);var gun=Gun(profile,pool);gun.StepSource(0,Input(),HandlingAction.Eject,false);gun.StepSource(0,Input(false,false,profile.Offer),HandlingAction.Sample,false);gun.StepSource(0,Input(false,true,profile.Offer),HandlingAction.Sample,false);gun.StepSource(0,Input(false,true,profile.Insert),HandlingAction.Sample,false);Check(gun.Snapshot.Phase==ReloadPhase.NeedsRack&&gun.Snapshot.Seated==profile.Capacity,profile.Id+" actual source magazine-home Z/scale supports physical upward seating");gun.StepSource(0,Input(false,false,profile.Charging),HandlingAction.Sample,false);gun.StepSource(0,Input(false,true,profile.Charging),HandlingAction.Sample,false);gun.StepSource(.12f,Input(false,true,new Float3(profile.Charging.X,profile.Charging.Y,profile.Charging.Z-.076f)),HandlingAction.Sample,false);Check(gun.Snapshot.Phase==ReloadPhase.Ready&&gun.Snapshot.Chambered&&pool.Available==1200,profile.Id+" real released/regripped BACK handle chambers finite source magazine");}
  var query=new Query();var round=new R23RoundState(new[]{"dummy"},query,true);foreach(var p in profiles)Check(round.ReadReserve(p.Id)==1200,p.Id+" production round observes actual sharedSMG1200 pool");round.SelectWeapon("p90");round.Step(0,Input(),false,false);round.Step(0,Input(true),false,false);Check(round.Hit("dummy",new Float3(),new Float3(0,0,150),false,"p90")&&round.LastTargetDamage("dummy")==20,"P90 accepted native shot applies exact source body20 through real HealthService at150m");round.Step(0,Input(),true,false);Check(round.ReadReserve("ump")==1244&&round.ReadReserve("p90")==1244&&round.ReadReserve("mp5")==1244&&round.ReadReserve("mp9")==1244&&round.ReadReserve("cx4")==2400&&round.ReadReserve("px4")==1200,"production SMG tactical refund is shared only by actual SMG family, never rifle/pistol");
  var desktop=Input();desktop.Desktop=true;round.Step(0,desktop,true,false);Check(round.ActiveSnapshot.Phase==ReloadPhase.NeedsRack&&round.ActiveLoaded==45&&round.ActiveReserve==1199,"explicit desktop shortcut still seats source top magazine with actual reserve debit");round.Step(0,Input(),true,false);Check(round.ActiveSnapshot.Phase==ReloadPhase.NeedsMagazine&&round.ActiveLoaded==0&&round.ActiveReserve==1244,"production Round VR P90 reload requests real Eject from seated stage");
  foreach(var p in new[]{SourceRifleDefinition.Mp5,SourceRifleDefinition.Mp9}){round.SelectWeapon(p.Id);round.Step(.2f,Input(),false,false);Check(round.Step(0,Input(true),false,false)&&round.Hit("dummy",new Float3(),new Float3(0,0,3),true,p.Id)&&round.LastTargetDamage("dummy")==p.HeadDamage,p.Id+" production headshot uses source listed0991 damage and real health");}
  string stable=round.ActiveInstanceId;int rounds=round.ActiveLoaded;round.SelectWeapon("cx4");round.SelectWeapon("mp9");Check(round.ActiveInstanceId==stable&&round.ActiveLoaded==rounds&&round.ActiveReserve==1244,"switching returns exact SMG instance/native magazine/family reserve without refill");
  var controls=new R23MagazineControls();Check(controls.Project(true,true,true,0,-.8f)==HandlingAction.Sample,"new source controls refuse recovered held click/stick before neutral");controls.Project(true,false,true,0,0);Check(controls.Project(true,true,true,0,0)==HandlingAction.Eject&&controls.Project(true,true,true,0,0)==HandlingAction.Sample,"source physical click requests Eject once, not repeated stage advance");controls.Project(true,false,true,0,0);Check(controls.Project(true,false,true,0,-.8f)==HandlingAction.Eject&&controls.Project(true,false,true,0,-.8f)==HandlingAction.Sample,"source stick-down eject is neutral-rearmed and single-use");controls.Project(false,false,true,0,0);Check(controls.Project(true,true,true,0,-.8f)==HandlingAction.Sample,"pause/tracking controls reset prevents held stick/click eject on resume");
  foreach(var p in profiles){var feedback=new R23WeaponFeedbackState(p.Id);Check(feedback.AcceptedShot(1,false)&&feedback.AcceptedShots==1&&!feedback.AcceptedShot(1,false),p.Id+" source feedback follows accepted native serial once");feedback.Advance(.05f);Check(feedback.Distance>0&&feedback.Bloom>0,p.Id+" source recoil and bloom are render observations over actual shot");feedback.ClearPresentation();Check(feedback.Distance==0&&feedback.PitchRadians==0&&feedback.AcceptedShots==1,p.Id+" holster/focus clears effects without changing shot identity");}
  Check(R23WeaponPickupRules.CatalogIndex("ump")==6&&R23WeaponPickupRules.CatalogIndex("p90")==10&&R23WeaponPickupRules.CatalogIndex("mp5")==17&&R23WeaponPickupRules.CatalogIndex("mp9")==18,"new world pickup tie identities match actual source catalog");
  Console.WriteLine(count+" focused real-owner four-SMG cases passed");return 0;
 }catch(Exception error){Console.WriteLine(error);return 1;}}
}
